mapper.update:
UPDATE sys.user_info SET lgn_fail_cnt=lgn_fail_cnt+1,
    user_stts_cd=CASE WHEN lgn_fail_cnt+1 >=5 THEN 'LOCKED' ELSE user_stts_cd END,
    lock_at=CASE WHEN lgn_fail_cnt+1 >=5 THEN CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul' ELSE lock_at END WHERE user_id=#{userId}

mapper.select:
SELECT tkn_id,user_id,tkn_hash,tkn_ty_cd,expir_at FROM sys.auth_tkn WHERE binding_hash=#{bindingHash} AND tkn_ty_cd='MFA'
AND issuance_stts_cd='ISSUED' AND use_at IS NULL AND revoked_at IS NULL AND expir_at > #{now}
AND EXISTS(SELECT 1 FROM sys.mail_outbox o WHERE o.auth_tkn_id=sys.auth_tkn.tkn_id AND o.send_stts_cd='SENT')

SELECT tkn_id,user_id,tkn_hash,tkn_ty_cd,expir_at FROM sys.auth_tkn WHERE tkn_hash=#{hash} AND tkn_ty_cd='RESET'
AND issuance_stts_cd='ISSUED' AND use_at IS NULL AND revoked_at IS NULL AND expir_at > #{now}
AND EXISTS(SELECT 1 FROM sys.mail_outbox o WHERE o.auth_tkn_id=sys.auth_tkn.tkn_id AND o.send_stts_cd='SENT')
